--- SELinux HTTPS port labels ---
http_port_t                    tcp      80, 81, 443, 488, 8008, 8009, 8443, 9000
--- existing nginx files ---
/etc/nginx/fastcgi.conf 644 root:root
/etc/nginx/fastcgi.conf.default 644 root:root
/etc/nginx/fastcgi_params 644 root:root
/etc/nginx/fastcgi_params.default 644 root:root
/etc/nginx/koi-utf 644 root:root
/etc/nginx/koi-win 644 root:root
/etc/nginx/mime.types 644 root:root
/etc/nginx/mime.types.default 644 root:root
/etc/nginx/nginx.conf 644 root:root
/etc/nginx/nginx.conf.default 644 root:root
/etc/nginx/scgi_params 644 root:root
/etc/nginx/scgi_params.default 644 root:root
/etc/nginx/uwsgi_params 644 root:root
/etc/nginx/uwsgi_params.default 644 root:root
