command:
set -eu
cat > /etc/nginx/conf.d/https-8443.conf <<'NGINX_EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name _;

    ssl_certificate /etc/nginx/tls/server.crt;
    ssl_certificate_key /etc/nginx/tls/server.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers PROFILE=SYSTEM;
    ssl_session_cache shared:TLS:10m;
    ssl_session_timeout 10m;

    add_header Strict-Transport-Security "max-age=31536000" always;
    add_header X-Content-Type-Options "nosniff" always;
    default_type text/plain;
    return 200 "node1 HTTPS service is healthy\n";
}
NGINX_EOF
chmod 0644 /etc/nginx/conf.d/https-8443.conf
restorecon -F /etc/nginx/conf.d/https-8443.conf >/dev/null 2>&1 || true
if [ ! -e /etc/nginx/nginx.conf.pre-https-8443 ]; then
    cp -a /etc/nginx/nginx.conf /etc/nginx/nginx.conf.pre-https-8443
fi
sed -i '/^    server {$/,/^    }$/ s/^/# disabled-cleartext /' /etc/nginx/nginx.conf
nginx -t
systemctl enable --now nginx
systemctl enable --now nginx-cert-renew.timer
firewall-cmd --permanent --add-port=8443/tcp
firewall-cmd --add-port=8443/tcp
printf '%s\n' '--- active/enabled ---'
systemctl is-active nginx nginx-cert-renew.timer
systemctl is-enabled nginx nginx-cert-renew.timer
printf '%s\n' '--- listening/firewall ---'
ss -tlnp | grep ':8443 '
firewall-cmd --query-port=8443/tcp
firewall-cmd --permanent --query-port=8443/tcp

